// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.voice.stt/** * NOUS — STT Confidence Scorer (v2 Fix). * * Routes STT results to the brain with trust-level metadata. The brain uses * the trust level to decide: * *   - **HIGH** (> 0.85): process normally — execute commands, call LLM *   - **MEDIUM** (0.60-0.85): ask for confirmation on critical intents *     (call, delete, send, transfer money, etc.) *   - **LOW** (< 0.60): ask user to repeat — "Sorry, it's noisy. Could you *     repeat that?" * * ## Why This Matters * * Without confidence scoring, a noisy-room transcription like "call mom" * (actual: "call tom") would directly execute, calling the wrong person. * With confidence scoring, the brain sees MEDIUM trust and asks: * *   "I heard 'call mom' but I'm not sure. Did you mean call mom?" * * ## Critical Intents * * The brain defines a set of critical intents that ALWAYS require * confirmation at MEDIUM trust: * *   - CALL (calling someone) *   - SMS / EMAIL (sending messages) *   - DELETE (deleting data) *   - PAYMENT (transferring money) *   - SHARE (sharing location, files, photos) *   - INSTALL (installing apps) *   - SETTINGS (changing system settings) * * At LOW trust, ALL intents are held — the brain asks the user to repeat. * * ## Adaptive Thresholds * * Thresholds can be adjusted based on: *   - Environment (noisy room → raise MEDIUM threshold to 0.75) *   - User preference (cautious users → raise thresholds) *   - Recent accuracy (if user frequently corrects, raise thresholds) * * @see <a href="docs/strategy/module-5-strategy-v2.md">§22 STT Confidence Scoring</a> */class ConfidenceScorer(    /** Confidence threshold for HIGH trust (default 0.85). */    private val highThreshold: Float = DEFAULT_HIGH_THRESHOLD,    /** Confidence threshold for MEDIUM trust (default 0.60). */    private val mediumThreshold: Float = DEFAULT_MEDIUM_THRESHOLD,    /** Set of critical intent types that require confirmation at MEDIUM trust. */    private val criticalIntents: Set<String> = DEFAULT_CRITICAL_INTENTS,) {    /**     * Score an STT result and produce a routing decision.     *     * @param result STT result to score     * @return routing decision with trust level and action     */    fun score(result: SttResult): ConfidenceRouting {        val trustLevel = SttTrustLevel.fromConfidence(result.confidence)        val action = when (trustLevel) {            SttTrustLevel.HIGH -> ConfidenceAction.PROCESS_NORMALLY            SttTrustLevel.MEDIUM -> {                // Check if the transcribed text contains critical intent keywords                if (containsCriticalIntent(result.text)) {                    ConfidenceAction.ASK_FOR_CONFIRMATION                } else {                    ConfidenceAction.PROCESS_NORMALLY                }            }            SttTrustLevel.LOW -> ConfidenceAction.ASK_TO_REPEAT        }        return ConfidenceRouting(            result = result,            trustLevel = trustLevel,            action = action,            detectedCriticalIntent = if (action == ConfidenceAction.ASK_FOR_CONFIRMATION) {                findCriticalIntent(result.text)            } else {                null            },            scorerThresholds = ScorerThresholds(highThreshold, mediumThreshold),        )    }    /**     * Check if the text contains any critical intent keywords.     *     * Uses simple keyword matching. For production, use the IntentClassifier     * (Module 2) to detect intent types properly.     */    private fun containsCriticalIntent(text: String): Boolean {        val lower = text.lowercase()        return criticalIntents.any { keyword ->            lower.contains(keyword)        }    }    /** Find which critical intent keyword was detected. */    private fun findCriticalIntent(text: String): String? {        val lower = text.lowercase()        return criticalIntents.firstOrNull { keyword ->            lower.contains(keyword)        }    }    companion object {        /** Default HIGH trust threshold. */        const val DEFAULT_HIGH_THRESHOLD = 0.85f        /** Default MEDIUM trust threshold. */        const val DEFAULT_MEDIUM_THRESHOLD = 0.60f        /** Default set of critical intent keywords. */        val DEFAULT_CRITICAL_INTENTS: Set<String> = setOf(            // Calling            "call", "dial", "phone",            // Messaging            "send", "text", "sms", "email", "message",            // Deletion            "delete", "remove", "erase", "wipe", "clear",            // Payment            "pay", "transfer", "send money", "wire",            // Sharing            "share", "post", "upload",            // Installation            "install", "uninstall", "download app",            // System settings            "factory reset", "change password", "disable security",        )    }}/** * Confidence routing decision produced by [ConfidenceScorer.score]. */data class ConfidenceRouting(    /** The original STT result. */    val result: SttResult,    /** Trust level (HIGH / MEDIUM / LOW). */    val trustLevel: SttTrustLevel,    /** Action the brain should take. */    val action: ConfidenceAction,    /** Detected critical intent keyword (if any, only for ASK_FOR_CONFIRMATION). */    val detectedCriticalIntent: String?,    /** Thresholds used by the scorer (for diagnostics). */    val scorerThresholds: ScorerThresholds,)/** * Action the brain should take based on confidence routing. */enum class ConfidenceAction {    /** Process normally — execute command, call LLM. */    PROCESS_NORMALLY,    /** Ask for confirmation — "Did you mean call mom?" */    ASK_FOR_CONFIRMATION,    /** Ask to repeat — "Sorry, it's noisy. Could you repeat that?" */    ASK_TO_REPEAT,}/** * Thresholds used by the confidence scorer. */data class ScorerThresholds(    /** HIGH trust threshold. */    val highThreshold: Float,    /** MEDIUM trust threshold. */    val mediumThreshold: Float,)